                        execChainDefinition.addBefore(ChainElement.MAIN_TRANSPORT.name(), entry.interceptor, entry.name);
                        break;
                }
            }
        }

        customizeExecChain(execChainDefinition);

        NamedElementChain<AsyncExecChainHandler>.Node current = execChainDefinition.getLast();
        AsyncExecChainElement execChain = null;
        while (current != null) {
            execChain = new AsyncExecChainElement(current.getValue(), execChain);
            current = current.getPrevious();
        }

        Lookup<AuthSchemeFactory> authSchemeRegistryCopy = this.authSchemeRegistry;
        if (authSchemeRegistryCopy == null) {
            authSchemeRegistryCopy = RegistryBuilder.<AuthSchemeFactory>create()
                    .register(StandardAuthScheme.BASIC, BasicSchemeFactory.INSTANCE)
                    .register(StandardAuthScheme.DIGEST, DigestSchemeFactory.INSTANCE)
                    .register(StandardAuthScheme.BEARER, BearerSchemeFactory.INSTANCE)
                    .register(StandardAuthScheme.SCRAM_SHA_256, ScramSchemeFactory.INSTANCE)
                    .build();
        }
        Lookup<CookieSpecFactory> cookieSpecRegistryCopy = this.cookieSpecRegistry;
        if (cookieSpecRegistryCopy == null && !cookieManagementDisabled) {
            cookieSpecRegistryCopy = CookieSpecSupport.createDefault();
        }

        CookieStore cookieStoreCopy = this.cookieStore;
        if (cookieStoreCopy == null) {
            cookieStoreCopy = new BasicCookieStore();
        }

        CredentialsProvider credentialsProviderCopy = this.credentialsProvider;
        if (credentialsProviderCopy == null) {
            credentialsProviderCopy = new SystemDefaultCredentialsProvider();
        }

        TlsStrategy tlsStrategyCopy = this.tlsStrategy;
        if (tlsStrategyCopy == null) {
            tlsStrategyCopy = DefaultClientTlsStrategy.createDefault();
        }

        final MultihomeConnectionInitiator connectionInitiator = new MultihomeConnectionInitiator(ioReactor, dnsResolver);
        final InternalH2ConnPool connPool = new InternalH2ConnPool(connectionInitiator, host -> null, tlsStrategyCopy);
        connPool.setConnectionConfigResolver(connectionConfigResolver);

        List<Closeable> closeablesCopy = closeables != null ? new ArrayList<>(closeables) : null;
        if (closeablesCopy == null) {
            closeablesCopy = new ArrayList<>(1);
        }
        if (evictIdleConnections) {
            final IdleConnectionEvictor connectionEvictor = new IdleConnectionEvictor(connPool,
                    maxIdleTime != null ? maxIdleTime : TimeValue.ofSeconds(30L));
            closeablesCopy.add(connectionEvictor::shutdown);
            connectionEvictor.start();
        }
        closeablesCopy.add(connPool);

        return new InternalH2AsyncClient(
                ioReactor,
                execChain,
                pushConsumerRegistry,
                threadFactory != null ? threadFactory : new DefaultThreadFactory("httpclient-main", true),
                connPool,
                exchangeIdGeneratorCopy,
                routePlannerCopy,
                cookieSpecRegistryCopy,
                authSchemeRegistryCopy,
                cookieStoreCopy,
                credentialsProviderCopy,
                defaultRequestConfig,
                closeablesCopy,
                maxQueuedRequests);

    }

@Override
    public void processChallenge(
            final HttpHost host,
            final boolean challenged,
            final AuthChallenge authChallenge,
            final HttpContext context) throws MalformedChallengeException, AuthenticationException {

        Args.notNull(context, "HTTP context");

        if (authChallenge == null) {
            if (!challenged && this.state == State.CLIENT_FINAL_SENT) {
                zeroAndClearExpectedV();
                this.state = State.FAILED;
                throw new AuthenticationException("Missing SCRAM Authentication-Info");
            }
            throw new MalformedChallengeException("Null SCRAM challenge");
        }

        final Map<String, String> params = toParamMap(authChallenge.getParams());

        if (challenged) {
            // --- 401 path (WWW-Authenticate) ---
            final String scheme = authChallenge.getSchemeName();
            if (scheme == null || !StandardAuthScheme.SCRAM_SHA_256.equalsIgnoreCase(scheme)) {
                throw new MalformedChallengeException("Unexpected scheme: " + scheme);
            }

            final String data = params.get("data");
            if (data == null) {
                // initial announce (no data)
                this.realm = params.get("realm");
                this.state = State.ANNOUNCED;
                this.complete = false;
                zeroAndClearExpectedV();
                return;
            }

            final String sid = params.get("sid");
            if (sid == null || sid.isEmpty()) {
                zeroAndClearExpectedV();
                this.state = State.FAILED;
                throw new MalformedChallengeException("SCRAM server-first missing sid");
            }

            // server-first (data present)
            final String decoded;
            try {
                decoded = b64ToString(data);
            } catch (final MalformedChallengeException ex) {
                zeroAndClearExpectedV();
                this.state = State.FAILED;
                throw ex;
            }
            this.serverFirstRaw = decoded;

            final Map<String, String> attrs;
            try {
                attrs = parseAttrs(decoded);
            } catch (final MalformedChallengeException ex) {
                zeroAndClearExpectedV();
                this.state = State.FAILED;
                throw ex;
            }

            final String r = attrs.get("r");
            final String s = attrs.get("s");
            final String i = attrs.get("i");
            if (r == null || r.isEmpty() || s == null || s.isEmpty() || i == null || i.isEmpty()) {
                this.state = State.FAILED;
                throw new MalformedChallengeException("SCRAM server-first missing r/s/i");
            }
            if (this.clientNonce == null || !r.startsWith(this.clientNonce)) {
                this.state = State.FAILED;
                throw new AuthenticationException("SCRAM server nonce does not start with client nonce");
            }

            try {
                this.salt = B64D.decode(s);
                if (this.salt.length == 0) {
                    throw new IllegalArgumentException("empty salt");
                }
            } catch (final IllegalArgumentException e) {
                this.state = State.FAILED;
                throw new MalformedChallengeException("Invalid base64 salt", e);
            }
            try {
                this.iterations = Integer.parseInt(i);
                if (this.iterations <= 0) {
                    throw new NumberFormatException("i<=0");
                }
            } catch (final NumberFormatException e) {
                this.state = State.FAILED;
                throw new MalformedChallengeException("Invalid iteration count", e);
            }

            if (this.minIterationsRequired > 0 && this.iterations < this.minIterationsRequired) {
                this.state = State.FAILED;
                throw new AuthenticationException(
                        "SCRAM iteration count below required minimum: " + this.iterations + " < " + this.minIterationsRequired);
            }
            if (this.iterations > this.maxIterationsAllowed) {
                this.state = State.FAILED;
                throw new AuthenticationException(
                        "SCRAM iteration count above allowed maximum: " + this.iterations + " > " + this.maxIterationsAllowed);
            }
            if (this.warnMinIterations > 0 && this.iterations < this.warnMinIterations && LOG.isWarnEnabled()) {
                LOG.warn("SCRAM iteration count ({}) lower than recommended ({})", this.iterations, warnMinIterations);
            }

            this.sid = sid;
            this.serverNonce = r;
            this.state = State.SERVER_FIRST_RCVD;
            this.complete = false;
            zeroAndClearExpectedV();
            return;
        }

        if (this.state != State.CLIENT_FINAL_SENT) {
            final State currentState = this.state;
            zeroAndClearExpectedV();
            this.state = State.FAILED;
            throw new AuthenticationException("SCRAM final response out of sequence: " + currentState);
        }

        final String sid = params.get("sid");
        if (sid == null || sid.isEmpty()) {
            zeroAndClearExpectedV();
            this.state = State.FAILED;
            throw new MalformedChallengeException("SCRAM Authentication-Info missing sid");
        }
        if (this.sid == null || !this.sid.equals(sid)) {
            zeroAndClearExpectedV();
            this.state = State.FAILED;
            throw new AuthenticationException("SCRAM sid mismatch");
        }

        // --- final-response path (Authentication-Info on any status) ---
        // For Authentication-Info, RFC 7804 does NOT mandate a scheme token; do NOT enforce scheme name here.
        final String data = params.get("data");
        if (data == null) {
            zeroAndClearExpectedV();
            this.state = State.FAILED;
            throw new MalformedChallengeException("SCRAM Authentication-Info missing data");
        }
        final String decoded;
        try {
            decoded = b64ToString(data);
        } catch (final MalformedChallengeException ex) {
            zeroAndClearExpectedV();
            this.state = State.FAILED;
            throw ex;
        }
        final Map<String, String> attrs;
        try {
            attrs = parseAttrs(decoded);
        } catch (final MalformedChallengeException ex) {
            zeroAndClearExpectedV();
            this.state = State.FAILED;
            throw ex;
        }
        final String err = attrs.get("e");
        if (err != null) {
            this.state = State.FAILED;
            if (err.isEmpty()) {
                throw new MalformedChallengeException("SCRAM server error attribute 'e' is empty");
            }
            throw new AuthenticationException("SCRAM server error: " + err);
        }
        final String vB64 = attrs.get("v");
        if (vB64 == null) {
            zeroAndClearExpectedV();
            this.state = State.FAILED;
            throw new MalformedChallengeException("SCRAM Authentication-Info missing v");
        }

        // compare 'v' in constant time; treat bad base64 for v as a signature mismatch (tests expect "signature")
        final byte[] expected = this.expectedV;
        this.expectedV = null; // clear reference early

        byte[] vBytes = null;
        boolean match;
        try {
            vBytes = B64D.decode(vB64);
            match = expected != null && MessageDigest.isEqual(expected, vBytes);
        } catch (final IllegalArgumentException e) {
            match = false; // invalid base64 for v -> treat as mismatch
        } finally {
            zero(vBytes);
            zero(expected);
        }

        if (!match) {
            this.state = State.FAILED;
            throw new MalformedChallengeException("SCRAM server signature mismatch");
        }
        this.complete = true;
        this.state = State.COMPLETE;
    }

